'use strict';
const E=EnsembleModel,$=s=>document.querySelector(s);let lang='es',tab='bagging',step=0,fold=0,member=0,bagPanel='ensemble',saved=[];
const cfg={kind:'wave',noise:.2,seed:42,count:12,depth:4,minLeaf:3,bootstrap:true,rounds:20,boostDepth:2,rate:.1,k:7,alpha:.1};let data,bag,boost,stack,single;
const tr=(a,b)=>lang==='es'?a:b,f=v=>Number(v).toFixed(3),names=()=>[tr('A · Regresión lineal','A · Linear regression'),'B · kNN',tr('C · Árbol','C · Tree')];
function compute(){data=E.dataset(cfg.kind,cfg.noise,cfg.seed);single=E.tree(data.train,cfg.depth,cfg.minLeaf);bag=E.bagging(data.train,cfg);boost=E.boosting(data.train,{count:cfg.rounds,depth:cfg.boostDepth,minLeaf:cfg.minLeaf,rate:cfg.rate});stack=E.stacking(data.train,cfg);member=Math.min(member,cfg.count-1);}compute();
const key=()=>JSON.stringify({tab,cfg}),dataKey=c=>[c.kind,c.noise,c.seed].join('|');const current=()=>tab==='bagging'?bag:tab==='boosting'?boost:stack;
function announce(s){$('#status').textContent=s;}
function range(id,label,min,max,increment){return `<label for="${id}">${label}: <output id="${id}Value">${cfg[id]}</output></label><input id="${id}" type="range" min="${min}" max="${max}" step="${increment}" value="${cfg[id]}">`;}
function renderControls(){if(problem==='classification'){classificationControls();return;}if(tab==='adaboost'){adaControls();return;}const common=`<p class="eyebrow">${tr('El mismo experimento','The same experiment')}</p><h2>${tr('Datos y modelos','Data & models')}</h2><label for="kind">${tr('Patrón que genera y','Pattern generating y')}</label><select id="kind">${['wave','steps','linear'].map((k,i)=>`<option value="${k}" ${cfg.kind===k?'selected':''}>${[tr('Onda no lineal','Nonlinear wave'),tr('Escalones','Steps'),tr('Recta','Straight line')][i]}</option>`).join('')}</select>${range('noise',tr('Ruido (desviación típica)','Noise (standard deviation)'),0,.6,.05)}<label for="seed">${tr('Semilla','Seed')} (1–9999)</label><input id="seed" type="number" min="1" max="9999" step="1" value="${cfg.seed}"><p class="note">${tr('90 ejemplos de entrenamiento · 60 de validación. La curva discontinua es la función generadora; los modelos solo ven los puntos de entrenamiento.','90 training samples · 60 validation samples. The dashed curve is the generating function; models only see training points.')}</p>`;
let specific=tab==='bagging'?`${range('count',tr('Número de árboles','Number of trees'),1,30,1)}${range('depth',tr('Profundidad máxima','Maximum depth'),1,7,1)}${range('minLeaf',tr('Mínimo por hoja','Minimum leaf size'),1,10,1)}<label class="check"><input id="bootstrap" type="checkbox" ${cfg.bootstrap?'checked':''}>${tr('Bootstrap: muestrear con reemplazo','Bootstrap: sample with replacement')}</label><p class="note">${tr('Sin bootstrap, se repite exactamente el mismo árbol: añadir copias no aporta diversidad.','Without bootstrap, the exact same tree is repeated: adding copies brings no diversity.')}</p>`:tab==='boosting'?`${range('rounds',tr('Iteraciones / árboles','Iterations / trees'),1,60,1)}${range('rate',tr('Learning rate η','Learning rate η'),.05,1,.05)}${range('boostDepth',tr('Profundidad de cada árbol','Depth of each tree'),1,3,1)}${range('minLeaf',tr('Mínimo por hoja','Minimum leaf size'),1,10,1)}<p class="note">${tr('Gradient boosting para pérdida cuadrática. Cada árbol aprende los residuos actuales. No es AdaBoost.','Gradient boosting for squared loss. Each tree learns the current residuals. This is not AdaBoost.')}</p>`:tab==='stacking'?`${range('k',tr('Vecinos de B (kNN)','Neighbors for B (kNN)'),1,15,1)}${range('depth',tr('Profundidad de C (árbol)','Depth of C (tree)'),1,7,1)}${range('minLeaf',tr('Mínimo por hoja de C','Minimum leaf size for C'),1,10,1)}${range('alpha',tr('Regularización del metamodelo (λ)','Meta-model regularization (λ)'),.01,1,.01)}<p class="note">${tr('Metamodelo: regresión ridge con intercepto. Los coeficientes pueden ser negativos y no tienen que sumar 1.','Meta-model: ridge regression with intercept. Coefficients may be negative and need not sum to 1.')}</p>`:`<p>${tr('Guarda configuraciones en las otras pestañas. Los cambios de controles no eliminan los resultados guardados.','Save configurations in the other tabs. Control changes do not remove saved results.')}</p>`;
$('#controls').innerHTML=common+specific+(tab!=='compare'?`<button class="primary-button" id="save"></button><p class="note" id="countSaved"></p><p class="note">${tr('Guardar conserva el ensemble completo, no el árbol o fold seleccionado. Máximo 6; disponibles hasta recargar.','Saving preserves the full ensemble, not the selected tree or fold. Up to 6; available until reload.')}</p>`:'');
$('#kind').onchange=e=>update('kind',e.target.value);$('#seed').onchange=e=>{if(!e.target.checkValidity()){e.target.reportValidity();e.target.value=cfg.seed;return;}update('seed',+e.target.value);};$('#controls').querySelectorAll('input[type=range]').forEach(el=>el.oninput=()=>{cfg[el.id]=+el.value;$('#'+el.id+'Value').textContent=el.value;compute();renderView();saveState();announce('');});if($('#bootstrap'))$('#bootstrap').onchange=e=>update('bootstrap',e.target.checked);if($('#save'))$('#save').onclick=save;saveState();}
function update(k,v){cfg[k]=v;compute();renderView();saveState();announce('');}
function saveState(){if(!$('#save'))return;const exists=saved.some(s=>s.key===key());$('#save').disabled=exists||saved.length>=6;$('#save').textContent=exists?tr('Configuración ya guardada','Configuration already saved'):saved.length>=6?tr('Comparación completa (6/6)','Comparison full (6/6)'):tr('Guardar modelo final para comparar','Save final model to compare');$('#countSaved').textContent=`${saved.length}/6 `+tr('configuraciones guardadas','saved configurations');}
function save(){if(saved.length>=6||saved.some(s=>s.key===key()))return;saved.push({key:key(),tab,cfg:{...cfg},model:current(),data});saveState();announce(tr('Guardado. Puedes cambiar parámetros o abrir Comparación.','Saved. Change parameters or open Compare.'));}
function render(){pauseAnimation();$('#problem').value=problem;$('#problem-label').textContent=tr('Tipo de problema','Problem type');$('#problem').options[0].textContent=tr('Clasificación','Classification');$('#problem').options[1].textContent=tr('Regresión','Regression');document.documentElement.lang=lang;$('#eyebrow').textContent=tr('Ensembles · UPM · Aprende experimentando','Ensembles · UPM · Learn by experimenting');$('#title').textContent=tr('Varios modelos. Una predicción.','Many models. One prediction.');$('#intro').textContent=tr('Promedia árboles, corrige residuos y aprende a combinar modelos. Observa cuándo mejora la validación y cuándo no.','Average trees, correct residuals and learn to combine models. Observe when validation improves and when it does not.');$('#tabs').innerHTML=['bagging',...(problem==='classification'?['adaboost']:[]),'boosting','stacking','compare'].map((t,i)=>`<button data-tab="${t}" aria-current="${t===tab}">${i+1}. ${t==='compare'?tr('Comparar guardados','Compare saved'):t==='adaboost'?'AdaBoost':t==='boosting'?'Gradient Boosting':t[0].toUpperCase()+t.slice(1)}</button>`).join('');$('#tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();announce('');});renderControls();renderView();}
function metric(model,d=data){return `<div class="scores"><div>RMSE · ${tr('entrenamiento','training')}<strong>${f(E.rmse(model,d.train))}</strong></div><div>RMSE · ${tr('validación','validation')}<strong>${f(E.rmse(model,d.validation))}</strong></div></div>`;}
const canvas=(id='plot',height=400)=>`<canvas id="${id}" width="850" height="${height}" role="img" aria-label="${tr('Datos y curvas de predicción','Data and prediction curves')}"></canvas>`;
function legend(extra=''){return `<p class="legend"><span style="color:#225b9a">● ${tr('Puntos azules: entrenamiento','Blue dots: training')}</span><span style="color:#b95820">□ ${tr('Cuadrados naranjas: validación','Orange squares: validation')}</span><span class="truth">-- ${tr('Función real','True function')}</span><span class="ensemble">━ ${tr('Ensemble','Ensemble')}</span>${extra}</p>`;}
function graph(id,model,d=data,others=[],residual=false){const c=$('#'+id),ctx=c.getContext('2d'),w=c.width,h=c.height,p=40;const xs=Array.from({length:161},(_,i)=>i/160),ys=[...d.train.map(r=>r.y),...d.validation.map(r=>r.y),...xs.map(x=>model.predict(x)),...others.flatMap(o=>xs.map(x=>o.model.predict(x)))];if(!residual)ys.push(...xs.map(x=>E.truth(x,d.kind)));let lo=Math.min(...ys)-.15,hi=Math.max(...ys)+.15;const px=x=>p+x*(w-2*p),py=y=>h-p-(y-lo)/(hi-lo)*(h-2*p);ctx.clearRect(0,0,w,h);ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.font='12px system-ui';ctx.fillStyle='#62717b';for(let j=0;j<5;j++){const y=lo+(hi-lo)*j/4;ctx.strokeStyle='#e5ecec';ctx.beginPath();ctx.moveTo(p,py(y));ctx.lineTo(w-p,py(y));ctx.stroke();ctx.fillText(y.toFixed(1),3,py(y)+4);}ctx.fillText('0',p,h-18);ctx.fillText('1',w-p,h-18);ctx.fillText('x',w/2,h-5);ctx.fillText(residual?tr('residuo','residual'):'y',5,18);
function line(fn,color,width,dash=[]){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.beginPath();xs.forEach((x,i)=>i?ctx.lineTo(px(x),py(fn(x))):ctx.moveTo(px(x),py(fn(x))));ctx.stroke();ctx.setLineDash([]);}others.forEach(o=>line(x=>o.model.predict(x),o.color||'#b2c4d5',o.width||1));if(!residual)line(x=>E.truth(x,d.kind),'#08776f',2,[6,5]);for(const [rows,validation] of [[d.train,false],[d.validation,true]])rows.forEach(r=>{ctx.beginPath();ctx.fillStyle='#225b9a';ctx.strokeStyle='#c9692c';if(validation){ctx.rect(px(r.x)-3,py(r.y)-3,6,6);ctx.stroke();}else{ctx.arc(px(r.x),py(r.y),2.8,0,Math.PI*2);ctx.fill();}});line(x=>model.predict(x),'#7c3aed',3);}
function guide(title,question,answer){return `<section class="card guide"><h2>${title}</h2><p>${question}</p><details><summary>${tr('Ver explicación','Show explanation')}</summary><p>${answer}</p></details></section>`;}
function drawBag(){const c=$('#bag-plot'),ctx=c.getContext('2d'),p=45,w=c.width,h=c.height,counts=new Map();bag.bags[member].forEach(id=>counts.set(id,(counts.get(id)||0)+1));const lo=Math.min(...data.train.map(r=>r.y))-.15,hi=Math.max(...data.train.map(r=>r.y))+.15,px=x=>p+x*(w-2*p),py=y=>h-p-(y-lo)/(hi-lo)*(h-2*p);ctx.fillStyle='white';ctx.fillRect(0,0,w,h);ctx.font='12px system-ui';for(let i=0;i<5;i++){const y=lo+(hi-lo)*i/4;ctx.strokeStyle='#e5ecec';ctx.beginPath();ctx.moveTo(p,py(y));ctx.lineTo(w-p,py(y));ctx.stroke();ctx.fillStyle='#526272';ctx.fillText(y.toFixed(1),5,py(y)+4);}ctx.fillText('x',w/2,h-6);ctx.fillText('y',8,20);ctx.fillText('0',p,h-20);ctx.fillText('1',w-p,h-20);data.train.slice().sort((a,b)=>(counts.get(a.id)||0)-(counts.get(b.id)||0)).forEach(r=>{const n=counts.get(r.id)||0,x=px(r.x),y=py(r.y);ctx.beginPath();ctx.arc(x,y,n?3+Math.sqrt(n)*2:4,0,Math.PI*2);ctx.fillStyle=n>1?'#7c3aed':n===1?'#225b9a':'#d1d5db';ctx.fill();ctx.strokeStyle=n?'#fff':'#9ca3af';ctx.lineWidth=1;ctx.stroke();if(n>1){ctx.fillStyle='#6022a7';ctx.font='bold 12px system-ui';ctx.fillText('×'+n,x+7,y-6);}});}
function bagContents(){const counts=new Map();bag.bags[member].forEach(id=>counts.set(id,(counts.get(id)||0)+1));return `<p class="flow"><strong>Bag ${member+1} → ${tr('Árbol','Tree')} ${member+1} → ${tr('predicción individual → media del ensemble','individual prediction → ensemble average')}</strong></p><p class="note">${tr('Los 90 ejemplos de entrenamiento, por ID. ×n indica cuántas veces entra cada ejemplo en este bag. Gris = fuera (OOB). Azul = una vez. Violeta = repetido.','All 90 training samples by ID. ×n indicates how many times each sample enters this bag. Gray = excluded (OOB). Blue = once. Purple = repeated.')}</p><p class="note">${tr('Solo se muestran datos de entrenamiento. Un ejemplo repetido conserva sus coordenadas; no son puntos nuevos.','Only training data are shown. A repeated sample keeps its coordinates; these are not new points.')}</p><details><summary>${tr('Ver los 90 IDs y sus repeticiones','Show all 90 IDs and their counts')}</summary><div class="bag-grid">${data.train.map(r=>{const count=counts.get(r.id)||0;return `<span class="bag-item ${count===0?'excluded':count>1?'repeated':'included'}" title="x=${f(r.x)}, y=${f(r.y)}">ID ${r.id}<strong>×${count}</strong></span>`;}).join('')}</div></details>${cfg.bootstrap?'':`<p class="note">${tr('Bootstrap desactivado: todos los bags contienen los mismos 90 ejemplos una vez. Por eso todos los árboles son idénticos.','Bootstrap disabled: every bag contains the same 90 samples once. That is why all trees are identical.')}</p>`}`;}
function bagView(){const oob=bag.oob(),unique=new Set(bag.bags[member]).size;$('#view').innerHTML=`<section class="card"><p class="eyebrow">BOOTSTRAP → ${tr('ÁRBOLES','TREES')} → ${tr('MEDIA','AVERAGE')}</p><h2>${tr('¿Qué cambia al promediar?','What changes when we average?')}</h2><p class="flow">${tr('Regresión: azul = entrenamiento · naranja = validación.','Regression: blue = training · orange = validation.')}</p><div class="member-selector"><label for="member">${tr('Selecciona el bag y su árbol','Select the bag and its tree')} · <output id="memberValue">${member+1}</output> / ${cfg.count}</label><select id="member">${bag.models.map((_,i)=>`<option value="${i}" ${i===member?'selected':''}>Bag ${i+1} → ${tr('Árbol','Tree')} ${i+1}</option>`).join('')}</select></div><div class="tabs bag-tabs" aria-label="${tr('Vista del árbol seleccionado','Selected tree view')}"><button type="button" data-bag-panel="prediction" aria-current="${bagPanel==='prediction'}">${tr('Predicción','Prediction')}</button><button type="button" data-bag-panel="sample" aria-current="${bagPanel==='sample'}">Bag ${member+1}</button></div><div class="model-bag-pair"><div ${bagPanel==='prediction'?'':'hidden'}><h3>${tr('Predicción del árbol','Tree prediction')} ${member+1}</h3>${canvas('plot',260)}${legend(`<span style="color:#b95820">━ ${tr('Árbol seleccionado','Selected tree')} ${member+1}</span><span>${tr('Gris: otros árboles','Gray: other trees')}</span>`)}</div><div ${bagPanel==='sample'?'':'hidden'}><h3>Bag ${member+1} → ${tr('Árbol','Tree')} ${member+1}</h3>${canvas('bag-plot',260)}<p class="legend"><span style="color:#225b9a">● ${tr('Una vez','Once')}</span><span style="color:#7c3aed">● ${tr('Repetido ×n','Repeated ×n')}</span><span style="color:#657180">● ${tr('No usados por este árbol','Not used by this tree')}</span></p><p class="note">${tr('Estos son los datos que entrenan el árbol naranja de la pestaña Predicción. El tamaño y ×n indican las repeticiones; los ejemplos grises no participan.','These data train the orange tree in the Prediction tab. Size and ×n indicate repeated draws; gray samples do not participate.')}</p></div></div><h3>${tr('Árbol seleccionado','Selected tree')} ${member+1}</h3>${metric(bag.models[member])}<p class="note">${tr('RMSE sobre todo el entrenamiento original y validación.','RMSE on the full original training set and validation.')}</p><details><summary>${tr('Ver RMSE del ensemble','Show ensemble RMSE')}</summary>${metric(bag)}</details><p class="note">${tr('RMSE menor = mejor. Árbol único sobre todo el entrenamiento','Lower RMSE = better. Single tree on all training data')}: ${tr('validación','validation')} <strong>${f(E.rmse(single,data.validation))}</strong>. ${tr('Misma profundidad y mínimo por hoja.','Same depth and minimum leaf size.')}</p></section><details class="card"><summary>${tr('Detalles del bag y evaluación OOB','Bag details and OOB evaluation')}</summary><p>${tr('Cada árbol se entrena únicamente con su bag de 90 extracciones del entrenamiento. Los cuadrados de validación nunca entran en los bags. Todos los árboles usan el mismo algoritmo y parámetros; cambia la muestra.','Each tree trains only on its own bag of 90 draws from training. Validation squares never enter the bags. All trees use the same algorithm and parameters; the sample changes.')}</p>${bagContents()}<div class="scores"><div>${tr('Extracciones','Draws')}<strong>90</strong></div><div>${tr('Ejemplos distintos','Distinct samples')}<strong>${unique}</strong></div><div>${tr('Fuera de esta muestra','Outside this sample')}<strong>${90-unique}</strong></div></div><p>${tr('IDs de las primeras 20 extracciones (los repetidos son el mismo ejemplo)','IDs of the first 20 draws (repeated IDs are the same sample)')}: <span class="equation">${bag.bags[member].slice(0,20).join(', ')}</span></p><p class="note">${tr('Un bag estándar hace n extracciones. Incluye cerca del 63,2% de los ejemplos distintos en promedio, no en cada muestra.','A standard bag makes n draws. It includes about 63.2% of distinct samples on average, not in every sample.')}</p><details class="flow"><summary>${tr('Opcional: evaluación con ejemplos fuera del bag (OOB)','Optional: evaluation with out-of-bag samples (OOB)')}</summary><p>${tr('Es una estimación adicional del error. Para comparar los modelos del laboratorio, utiliza las métricas principales de entrenamiento y validación.','This is an additional error estimate. To compare models in this lab, use the main training and validation metrics.')}</p><h3>${tr('¿Qué significa OOB?','What does OOB mean?')}</h3><p><strong>OOB = out-of-bag = ${tr('fuera del bag','outside the bag')}.</strong> ${tr('Son ejemplos de entrenamiento que no se extrajeron para este árbol. En el gráfico aparecen en gris.','These are training samples that were not drawn for this tree. They appear in gray in the plot.')}</p><p><strong>${tr('Árbol','Tree')} ${member+1}: ${unique} ${tr('ejemplos distintos usados','distinct samples used')} + ${90-unique} ${tr('ejemplos fuera del bag (OOB)','samples outside the bag (OOB)')} = 90.</strong></p><p>${tr('Un mismo ejemplo puede estar dentro del bag de un árbol y fuera del bag de otro.','The same sample may be inside one tree’s bag and outside another’s.')}</p><details><summary>${tr('¿Cómo calculamos el error OOB del ensemble?','How do we calculate the ensemble’s OOB error?')}</summary><ol><li>${tr('Para cada ejemplo de entrenamiento, buscamos los árboles que no lo usaron.','For each training sample, find the trees that did not use it.')}</li><li>${tr('Promediamos solo las predicciones de esos árboles y las comparamos con su valor real.','Average only those trees’ predictions and compare with the true value.')}</li><li>${tr('Calculamos RMSE sobre los ejemplos que tienen al menos una predicción de este tipo.','Calculate RMSE over samples with at least one such prediction.')}</li></ol><h3>${tr('Regresión: fórmula usada en este laboratorio','Regression: formula used in this lab')}</h3><p class="oob-formula">ŷ<sub>i</sub><sup>OOB</sup> = (1 / |T<sub>i</sub>|) ∑<sub>t ∈ Tᵢ</sub> f<sub>t</sub>(x<sub>i</sub>)</p><p class="oob-formula">RMSE<sub>OOB</sub> = √[ (1 / |S|) ∑<sub>i ∈ S</sub> (y<sub>i</sub> − ŷ<sub>i</sub><sup>OOB</sup>)² ]</p><ul><li>${tr('Tᵢ: árboles que no usaron el ejemplo de entrenamiento i. |Tᵢ| es su número.','Tᵢ: trees that did not use training sample i. |Tᵢ| is their count.')}</li><li>${tr('fₜ(xᵢ): predicción del árbol t; ŷᵢᴼᴼᴮ: promedio de las predicciones de esos árboles.','fₜ(xᵢ): prediction from tree t; ŷᵢᴼᴼᴮ: average prediction from those trees.')}</li><li>${tr('S: ejemplos de entrenamiento con al menos un árbol que no los usó. |S| es el número de ejemplos evaluables, no siempre los 90.','S: training samples with at least one tree that did not use them. |S| is the number of evaluable samples, not necessarily all 90.')}</li><li>${tr('yᵢ: valor real del ejemplo i. Si S está vacío, el RMSE OOB no está disponible.','yᵢ: true value of sample i. If S is empty, OOB RMSE is unavailable.')}</li></ul><h3>${tr('Clasificación: tasa de error OOB','Classification: OOB error rate')}</h3><p>${tr('Como referencia: este laboratorio calcula regresión, no clasificación.','For reference: this lab computes regression, not classification.')}</p><p class="oob-formula">Error<sub>OOB</sub> = (1 / |S|) ∑<sub>i ∈ S</sub> 𝟙[ yᵢ ≠ ŷᵢ<sup>OOB</sup> ]</p><p>${tr('Aquí ŷᵢᴼᴼᴮ es la clase obtenida por votación entre los árboles de Tᵢ. El indicador 𝟙 vale 1 si la clase es incorrecta y 0 si es correcta. Multiplica por 100 para expresarlo como porcentaje.','Here ŷᵢᴼᴼᴮ is the class obtained by voting among the trees in Tᵢ. The indicator 𝟙 is 1 for an incorrect class and 0 for a correct class. Multiply by 100 to express it as a percentage.')}</p><p>${tr('OOB estima el error de generalización durante el entrenamiento. La evaluación final utiliza un conjunto de test independiente, cuyas predicciones combinan todos los árboles.','OOB estimates generalization error during training. Final evaluation uses an independent test set, with predictions combining all trees.')}</p><p>RMSE OOB: <strong>${oob.rmse===null?tr('No disponible','Unavailable'):f(oob.rmse)}</strong><br>${tr('Ejemplos evaluables','Evaluable samples')}: <strong>${Math.round(oob.coverage*90)} / 90</strong> (${(oob.coverage*100).toFixed(0)}%)</p><p>${tr('Si ningún árbol dejó fuera un ejemplo, no podemos evaluarlo así. Con más árboles suele haber más ejemplos evaluables.','If no tree left a sample out, we cannot evaluate it this way. More trees usually make more samples evaluable.')}</p></details><p><strong>${tr('OOB no es validación.','OOB is not the validation set.')}</strong> ${tr('Los 60 cuadrados naranjas están siempre separados del entrenamiento. Los ejemplos OOB pertenecen al entrenamiento, pero quedaron fuera de un bag concreto.','The 60 orange squares are always separate from training. OOB samples belong to training but were left out of a particular bag.')}</p></details></details>${guide(tr('Reto · Diversidad frente a copias','Challenge · Diversity versus copies'),tr('Desactiva bootstrap. Guarda un ensemble con Número de árboles = 1 y otro con Número de árboles = 20. Compáralos en Comparación. Después activa bootstrap y repite. El selector Bag → Árbol solo inspecciona un miembro, no el tamaño del ensemble.','Disable bootstrap. Save one ensemble with Number of trees = 1 and another with Number of trees = 20. Compare them in Compare. Then enable bootstrap and repeat. The Bag → Tree selector only inspects one member, not the ensemble size.'),tr('Sin bootstrap, los árboles deterministas son idénticos y su media es la misma curva. Con remuestreo, sus errores pueden compensarse. Bagging suele reducir la varianza, pero no garantiza mejorar cada conjunto de validación. Esto es bagging de árboles; no Random Forest con selección aleatoria de atributos.','Without bootstrap, deterministic trees are identical and their average is the same curve. With resampling, their errors may compensate. Bagging often reduces variance but does not guarantee improvement on every validation set. This is tree bagging, not Random Forest with random feature selection.'))}`;graph('plot',bag,data,bag.models.map((model,i)=>({model,color:i===member?'#d47a37':'#bdcbd7',width:i===member?2:1})));drawBag();document.querySelectorAll('[data-bag-panel]').forEach(b=>b.onclick=()=>{bagPanel=b.dataset.bagPanel;bagView();document.querySelector('[data-bag-panel="'+bagPanel+'"]').focus({preventScroll:true});});$('#member').onchange=e=>{member=+e.target.value;bagView();};}
function boostView(){const stage=Math.max(1,Math.min(cfg.rounds,boostStage)),partial={predict:x=>boost.predict(x,stage)},previous={predict:x=>boost.predict(x,stage-1)};$('#view').innerHTML=`<section class="card"><p class="eyebrow">GRADIENT BOOSTING · ${tr('PÉRDIDA CUADRÁTICA','SQUARED LOSS')}</p><h2>${tr('Cada árbol aprende los residuos','Each tree learns the residuals')}</h2>${animationButtons()}<div class="member-selector"><label for="stage">${tr('Inspeccionar iteración','Inspect iteration')}: ${stage} / ${cfg.rounds}</label><select id="stage">${boost.models.map((_,i)=>`<option value="${i+1}" ${i+1===stage?'selected':''}>${tr('Iteración','Iteration')} ${i+1}</option>`).join('')}</select></div><div class="tabs bag-tabs" aria-label="${tr('Vista de boosting','Boosting view')}"><button type="button" data-boost-panel="prediction" aria-current="${boostPanel==='prediction'}">${tr('Predicción','Prediction')}</button><button type="button" data-boost-panel="residual" aria-current="${boostPanel==='residual'}">${tr('Residuos','Residuals')}</button></div><div ${boostPanel==='prediction'?'':'hidden'}>${canvas('plot',260)}${legend(`<span>${tr('Naranja: ensemble antes del último árbol mostrado','Orange: ensemble before the last displayed tree')}</span>`)}</div><div ${boostPanel==='residual'?'':'hidden'}><h2>${tr('Qué aprende el árbol de esta iteración','What the tree learns at this iteration')}</h2>${canvas('residual',260)}<p class="legend">${tr('● Residuos de entrenamiento: y − F anterior · Morado: árbol hₘ antes de multiplicarlo por η.','● Training residuals: y − previous F · Purple: tree hₘ before multiplying by η.')}</p></div><p class="equation">F₀ = ${f(boost.initial)} · Fₘ(x) = Fₘ₋₁(x) + ${cfg.rate} × hₘ(x)</p>${boostPanel==='residual'?`<h3>${tr('Árbol de la iteración · RMSE sobre residuos','Iteration tree · RMSE on residuals')}</h3>${metric(boost.models[stage-1],{train:boost.residuals[stage-1],validation:data.validation.map(r=>({...r,y:r.y-previous.predict(r.x)}))})}`:`<h3>${tr('Ensemble hasta esta iteración','Ensemble through this iteration')}</h3>${metric(partial)}`}<p class="note">${tr('Las métricas y la curva muestran la iteración seleccionada. Guardar conserva el ensemble completo de','Metrics and curve show the selected iteration. Saving preserves the full ensemble of')} ${cfg.rounds} ${tr('árboles.','trees.')}</p><details><summary>${tr('Errores a lo largo del entrenamiento','Errors throughout training')}</summary><div class="table-wrap"><table><thead><tr><th>${tr('Árboles','Trees')}</th><th>RMSE ${tr('entrenamiento','training')}</th><th>RMSE ${tr('validación','validation')}</th></tr></thead><tbody>${[...new Set([0,1,Math.floor(cfg.rounds/2),cfg.rounds])].sort((a,b)=>a-b).map(i=>{const m={predict:x=>boost.predict(x,i)};return `<tr><td>${i}</td><td>${f(E.rmse(m,data.train))}</td><td>${f(E.rmse(m,data.validation))}</td></tr>`;}).join('')}</tbody></table></div></details></section>${guide(tr('Reto · Más árboles, ¿siempre mejor?','Challenge · More trees: always better?'),tr('Aumenta el ruido, prueba 10 y 60 árboles y compara η = 0,1 con η = 1. Mira entrenamiento y validación.','Increase noise, try 10 and 60 trees and compare η = 0.1 with η = 1. Inspect training and validation.'),tr('Para pérdida cuadrática, los residuos son la dirección del gradiente negativo. Un η menor reduce cada actualización. Más iteraciones pueden mejorar el ajuste y también aprender ruido. Early stopping usaría validación para decidir cuándo parar; aquí exploras esa decisión manualmente.','For squared loss, residuals give the negative-gradient direction. A smaller η shrinks each update. More iterations may improve fit and also learn noise. Early stopping would use validation to decide when to stop; here you explore that decision manually.'))}`;graph('plot',partial,data,[{model:previous,color:'#d47a37',width:2}]);graph('residual',boost.models[stage-1],{...data,train:boost.residuals[stage-1],validation:[]},[],true);document.querySelectorAll('[data-boost-panel]').forEach(b=>b.onclick=()=>{boostPanel=b.dataset.boostPanel;boostView();document.querySelector('[data-boost-panel="'+boostPanel+'"]').focus({preventScroll:true});});bindAnimation(()=>{if(boostStage>=cfg.rounds)return false;boostStage++;return boostStage<cfg.rounds;},()=>boostStage=1,boostView);$('#stage').onchange=e=>{pauseAnimation();boostStage=+e.target.value;boostView();};}
let boostStage=1,boostPanel='prediction';
function stackView(){const labels=['1. Generar OOF predictions','2. Train the meta-model','3. Refit & Predict'];let body='';
// Assemble the selected educational stage; all statistics come from actual fitted models.
if(step===0){body=`<h2>${tr('Generar predicciones OOF · modelos A, B y C','Generate OOF predictions · models A, B and C')}</h2><p><strong>OOF = out-of-fold.</strong> ${tr('Cada ejemplo recibe predicciones de modelos que no se entrenaron con él. Los folds pertenecen al entrenamiento; validación queda aparte.','Each sample receives predictions from models that did not train on it. Folds belong to training; validation remains separate.')}</p><div class="folds">${[0,1,2].map(i=>`<div class="fold ${fold===i?'held':''}">Fold ${i+1}<strong>${fold===i?tr('PREDECIR','PREDICT'):tr('ENTRENAR','TRAIN')}</strong>30 ${tr('ejemplos','samples')}</div>`).join('')}</div><p class="flow">${tr('Entrenar A (lineal), B (kNN) y C (árbol) desde cero con 60 ejemplos azules → los tres predicen los 30 ejemplos naranjas.','Train A (linear), B (kNN) and C (tree) from scratch on 60 blue samples → all three predict the 30 orange samples.')}<br><strong>3 ${tr('modelos','models')} × 3 folds = 9 ${tr('entrenamientos temporales','temporary training runs')}.</strong></p><p>${tr('Conservamos las predicciones OOF de cada ronda de validación cruzada. Al reunir las tres rondas obtenemos una tabla de 90 filas para entrenar el metamodelo. En el paso 3 entrenaremos los modelos finales con todos los datos de entrenamiento.','We keep the OOF predictions from each cross-validation round. Combining all three rounds yields a 90-row table for training the meta-model. In Step 3 we train the final models on all training data.')}</p>${oofTable()}${oofErrors()}`;}else if(step===1){body=`<h2>${tr('Aprender la combinación','Learn the combination')}</h2><div class="flow"><strong>${tr('¿Qué modelo aprende a combinar A, B y C?','Which model learns to combine A, B and C?')}</strong><p>${tr('En este laboratorio predecimos un valor numérico: usamos Ridge, una regresión lineal con regularización L2. Sus entradas son las tres predicciones OOF y su objetivo es el valor real. Aprende un intercepto y un coeficiente para cada modelo base; λ controla la penalización de esos coeficientes.','In this lab we predict a numerical value: we use Ridge, linear regression with L2 regularization. Its inputs are the three OOF predictions and its target is the true value. It learns an intercept and a coefficient for each base model; λ controls the penalty on those coefficients.')}</p><p>${tr('Para clasificación, podemos usar regresión logística como metamodelo: recibe las probabilidades OOF de los modelos base y aprende a predecir la clase real. Esta alternativa se explica aquí como referencia; el laboratorio implementa Ridge para regresión.','For classification, we can use logistic regression as the meta-model: it receives OOF probabilities from the base models and learns to predict the true class. This alternative is explained here for reference; the lab implements Ridge for regression.')}</p></div><p>${tr('El metamodelo usa 90 filas: las tres predicciones OOF son sus entradas; el valor real y es su objetivo. No se entrena sobre predicciones de modelos que ya vieron ese ejemplo.','The meta-model uses 90 rows: three OOF predictions are its inputs; the true y value is its target. It is not trained on predictions from models that already saw that sample.')}</p>${oofTable()}<p class="equation">ŷ = ${f(stack.meta.weights[0])} ${stack.meta.weights.slice(1).map((w,i)=>`${w>=0?'+':'−'} ${f(Math.abs(w))} × ${['A','B','C'][i]}`).join(' ')}</p><p class="note">${tr('Ridge minimiza MSE + λ Σw². No se penaliza el intercepto. Sus coeficientes no son probabilidades ni importancias causales.','Ridge minimizes MSE + λ Σw². The intercept is not penalized. Its coefficients are not probabilities or causal feature importances.')}</p>`;}else{body=`<h2>${tr('Entrenar los modelos base finales','Train final base models')}</h2><p class="flow">${tr('Entrenar un A, un B y un C nuevos con los 90 ejemplos de entrenamiento. Mantener fijo el metamodelo del paso 2.','Train a new A, B and C on all 90 training examples. Keep the meta-model from Step 2 fixed.')}</p>${canvas()}${legend(`<span>${tr('Curvas finas: A, B y C finales','Thin curves: final A, B and C')}</span>`)}${metric(stack)}<label for="probe">${tr('Ejemplo nuevo: valor de x','New sample: x value')} <output id="probeValue">0.50</output></label><input id="probe" type="range" min="0" max="1" step=".01" value=".5"><p id="prediction" class="flow"></p><div class="table-wrap"><table><thead><tr><th>${tr('Modelo','Model')}</th><th>RMSE ${tr('validación','validation')}</th></tr></thead><tbody>${stack.models.map((m,i)=>`<tr><td>${names()[i]}</td><td>${f(E.rmse(m,data.validation))}</td></tr>`).join('')}<tr class="active"><td>Stacking</td><td>${f(E.rmse(stack,data.validation))}</td></tr></tbody></table></div>`;}
$('#view').innerHTML=`<section class="card"><p class="eyebrow">STACKING · ${tr('REGRESIÓN','REGRESSION')}</p><div class="tabs">${labels.map((label,i)=>`<button data-step="${i}" aria-current="${step===i}">${label}</button>`).join('')}</div>${body}<div class="actions">${step>0?`<button id="previous" class="secondary">← ${tr('Anterior','Previous')}</button>`:''}${step<2?`<button id="next" class="primary-button">${tr('Siguiente paso','Next step')} →</button>`:''}</div></section>${guide(tr('Reto · ¿Por qué OOF?','Challenge · Why OOF?'),tr('Compara el árbol C con el ensemble. Cambia k, profundidad y λ. ¿Stacking siempre gana?','Compare tree C with the ensemble. Change k, depth and λ. Does stacking always win?'),tr('El metamodelo debe aprender de errores en ejemplos no vistos por los modelos base. Usar sus predicciones de entrenamiento sería demasiado optimista. OOF evita ese problema; no garantiza que combinar modelos supere al mejor de ellos. Los modelos finales aprovechan los 90 ejemplos, sin incorporar validación.','The meta-model must learn from errors on examples unseen by the base models. Their training predictions would be too optimistic. OOF avoids this problem; it does not guarantee that combining models beats the best one. Final models use all 90 samples without incorporating validation.'))}`;document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;fold=0;stackView();});document.querySelectorAll('[data-fold]').forEach(b=>b.onclick=()=>{fold=+b.dataset.fold;stackView();});if($('#next'))$('#next').onclick=()=>{step++;fold=0;stackView();};if($('#previous'))$('#previous').onclick=()=>{step--;fold=0;stackView();};if(step===2){graph('plot',stack,data,stack.models.map((model,i)=>({model,color:['#de9d39','#8baab6','#bf8f9c'][i]})));const probe=x=>{$('#probeValue').textContent=x.toFixed(2);$('#prediction').textContent=stack.models.map((m,i)=>`${['A','B','C'][i]}: ${f(m.predict(x))}`).join(' · ')+` → ${tr('Metamodelo','Meta-model')} → ŷ = ${f(stack.predict(x))}`;};$('#probe').oninput=e=>probe(+e.target.value);probe(.5);}}
function oofErrors(){const rows=names().map((name,j)=>{let trainSum=0,trainCount=0;stack.folds.forEach(split=>{const ids=new Set(split.trainIds);data.train.filter(r=>ids.has(r.id)).forEach(r=>{trainSum+=(r.y-split.models[j].predict(r.x))**2;trainCount++;});});const trainError=Math.sqrt(trainSum/trainCount),oofError=Math.sqrt(data.train.reduce((sum,r,i)=>sum+(r.y-stack.oof[i][j])**2,0)/data.train.length);return `<tr><th scope="row">${name}</th><td>${f(trainError)}</td><td>${f(oofError)}</td></tr>`;}).join('');return `<h3>${tr('Error de entrenamiento frente a error OOF','Training error versus OOF error')}</h3><div class="table-wrap"><table><thead><tr><th>${tr('Modelo','Model')}</th><th>RMSE ${tr('entrenamiento','training')}</th><th>RMSE OOF</th></tr></thead><tbody>${rows}</tbody></table></div><p>${tr('Entrenamiento: cada modelo entrenado en una ronda de validación cruzada predice los 60 ejemplos con los que se entrenó. OOF: predice los 30 que dejó fuera. Repetimos las tres rondas para A, B y C.','Training: each model trained in a cross-validation round predicts the 60 samples it trained on. OOF: it predicts the 30 held-out samples. Repeat all three rounds for A, B and C.')}</p><p class="note">${tr('RMSE de entrenamiento: raíz del promedio de los 180 errores cuadrados (60 × 3); cada ejemplo participa dos veces. RMSE OOF: raíz del promedio de los 90 errores cuadrados; cada ejemplo se evalúa una vez sin haber sido usado para entrenar ese modelo. La tabla usa todos los ejemplos, no solo las filas mostradas.','Training RMSE: square root of the average of 180 squared errors (60 × 3); each sample appears twice. OOF RMSE: square root of the average of 90 squared errors; each sample is evaluated once by a model that did not train on it. The table uses all samples, not just the displayed rows.')}</p><p>${tr('Cada predicción OOF se obtiene con un modelo que no utilizó ese ejemplo para entrenar. El RMSE OOF mide cuánto se alejan esas predicciones de los valores reales. Esta evaluación es de los modelos base; no es la evaluación del stacking completo ni sustituye al test final.','Each OOF prediction comes from a model that did not train on that sample. OOF RMSE measures how far these predictions are from the true values. This evaluates the base models; it does not evaluate the complete stacking model or replace the final test.')}</p>`;}
function oofTable(){return `<details open><summary>${tr('Predicciones OOF por fold','OOF predictions by fold')}</summary><div class="tabs">${[0,1,2].map(i=>`<button data-fold="${i}" aria-current="${fold===i}">Fold ${i+1}</button>`).join('')}</div><p>${tr('Los folds dividen los ejemplos, no los modelos. A (lineal), B (kNN) y C (árbol) comparten la misma partición. En cada bloque, los tres se entrenan con los otros dos folds y predicen los ejemplos del fold indicado.','Folds divide samples, not models. A (linear), B (kNN) and C (tree) share the same split. In each group, all three train on the other two folds and predict samples in the indicated fold.')}</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>${tr('Fold del ejemplo','Sample fold')}</th><th>OOF A · ${tr('lineal','linear')}</th><th>OOF B · kNN</th><th>OOF C · ${tr('árbol','tree')}</th><th>y ${tr('real','true')}</th></tr></thead><tbody>${[fold].map(g=>{const other=[1,2,3].filter(n=>n!==g+1).join(' + ');return `<tr class="oof-group ${g===fold?'active':''}"><th colspan="6" scope="rowgroup">${tr('Predecir','Predict')} fold ${g+1} · A, B, C ${tr('entrenados con folds','trained on folds')} ${other}</th></tr>`+data.train.map((r,i)=>({r,i})).filter(({i})=>i%3===g).slice(0,3).map(({r,i})=>`<tr class="${g===fold?'active':''}"><td>${r.id}</td><td>${g+1}</td>${stack.oof[i].map(v=>`<td>${f(v)}</td>`).join('')}<td>${f(r.y)}</td></tr>`).join('');}).join('')}</tbody></table></div><p class="note">${tr('Se muestran 3 ejemplos del fold seleccionado, ordenados por ID. Cada fold contiene 30 ejemplos. Las pestañas solo cambian la vista: el metamodelo utiliza las 90 filas de los tres folds.','Showing 3 samples from the selected fold, ordered by ID. Each fold contains 30 samples. Tabs only change the view: the meta-model uses all 90 rows from the three folds.')}</p></details>`;}
function summary(s){return s.tab==='bagging'?`${s.cfg.count} ${tr('árboles','trees')} · depth ${s.cfg.depth} · leaf ${s.cfg.minLeaf} · bootstrap ${s.cfg.bootstrap?tr('sí','yes'):'no'}`:s.tab==='boosting'?`${s.cfg.rounds} ${tr('árboles','trees')} · η ${s.cfg.rate} · depth ${s.cfg.boostDepth} · leaf ${s.cfg.minLeaf}`:`k ${s.cfg.k} · depth ${s.cfg.depth} · leaf ${s.cfg.minLeaf} · λ ${s.cfg.alpha}`;}
function compareView(){$('#view').innerHTML=`<section class="card"><h2>${tr('Comparar modelos finales guardados · Regresión','Compare saved final models · Regression')}</h2><p>${tr('Cada guardado contiene el ensemble completo: todos los árboles o iteraciones; en stacking, el resultado del paso 3. No es la ronda ni el fold inspeccionado. RMSE menor es mejor. Usa los mismos datos para comparar.','Each snapshot contains the full ensemble: all trees or iterations; for stacking, the Step 3 result. Not the inspected round or fold. Lower RMSE is better. Use the same data to compare.')}</p><button id="clear" class="secondary" ${saved.length?'':'disabled'}>${tr('Vaciar comparación','Clear comparison')}</button>${new Set(saved.map(s=>dataKey(s.cfg))).size>1?`<p class="flow">${tr('Atención: hay configuraciones con distinta regla, ruido o semilla. Sus métricas no aíslan el efecto del modelo.','Warning: some configurations use different patterns, noise or seeds. Their metrics do not isolate model effects.')}</p>`:''}</section><div class="comparison">${saved.map((s,i)=>`<section class="card"><h2>${i+1}. ${s.tab[0].toUpperCase()+s.tab.slice(1)}</h2><p class="note">${summary(s)}</p><p class="note">${tr('Datos','Data')}: ${s.cfg.kind} · ${tr('ruido','noise')} ${s.cfg.noise} · ${tr('semilla','seed')} ${s.cfg.seed}</p>${canvas('saved'+i)}${metric(s.model,s.data)}<button class="secondary remove" data-i="${i}">${tr('Eliminar','Remove')}</button></section>`).join('')}</div>${saved.length?'':`<section class="card"><p>${tr('No hay configuraciones guardadas. Empieza con Bagging y pulsa Guardar ensemble completo.','No saved configurations. Start with Bagging and click Save full ensemble.')}</p></section>`}<section class="card guide"><p>${tr('Esta validación ayuda a explorar y ajustar. Tras elegir parámetros, una evaluación final necesitaría un test independiente. No hay un ensemble que gane siempre.','This validation set supports exploration and tuning. After choosing parameters, a final evaluation would need an independent test set. No ensemble always wins.')}</p></section>`;saved.forEach((s,i)=>graph('saved'+i,s.model,s.data));$('#clear').onclick=()=>{saved=[];compareView();};document.querySelectorAll('.remove').forEach(b=>b.onclick=()=>{saved.splice(+b.dataset.i,1);compareView();});}
function renderView(){pauseAnimation();if(problem==='classification'){classView();return;}if(tab==='bagging')bagView();else if(tab==='adaboost')adaView();else if(tab==='boosting')boostView();else if(tab==='stacking')stackView();else compareView();}
let playback=null,adaSeed=42,adaCount=12,adaFrame=0,adaPanel='tree';
let adaData=E.classData(adaSeed),ada=E.adaBoost(adaData.train,adaCount);
function pauseAnimation(){if(playback!==null)clearInterval(playback);playback=null;}
function animationButtons(){return `<div class="actions"><button class="secondary" id="play">${playback===null?tr('▶ Reproducir','▶ Play'):tr('Ⅱ Pausa','Ⅱ Pause')}</button><button class="secondary" id="one-step">${tr('Paso →','Step →')}</button><button class="secondary" id="restart">${tr('↺ Reiniciar','↺ Restart')}</button></div>`;}
function bindAnimation(advance,reset,draw){$('#play').onclick=()=>{if(playback!==null){pauseAnimation();draw();return;}playback=setInterval(()=>{if(!advance())pauseAnimation();draw();},1400);draw();};$('#one-step').onclick=()=>{pauseAnimation();advance();draw();};$('#restart').onclick=()=>{pauseAnimation();reset();draw();};}
function adaControls(){$('#controls').innerHTML=`<p class="eyebrow">ADABOOST · ${tr('CLASIFICACIÓN','CLASSIFICATION')}</p><h2>${tr('Dos clases en el plano','Two classes in the plane')}</h2><p>${tr('60 puntos para entrenar y 40 para validar. La clase depende de si x₁ + x₂ supera 1. Cada árbol solo hace una pregunta.','60 training and 40 validation points. Class depends on whether x₁ + x₂ exceeds 1. Each tree asks just one question.')}</p><label for="ada-count">${tr('Máximo de rondas','Maximum rounds')}</label><input id="ada-count" type="range" min="1" max="60" value="${adaCount}"><output>${adaCount}</output><label for="ada-seed">${tr('Semilla','Seed')}</label><input id="ada-seed" type="number" min="1" max="9999" value="${adaSeed}"><p class="note">${tr('Este experimento es de clasificación. La comparación guardada de los otros métodos usa regresión y RMSE.','This experiment is classification. Saved comparisons for the other methods use regression and RMSE.')}</p>`;const change=()=>{pauseAnimation();adaCount=+$('#ada-count').value;adaSeed=+$('#ada-seed').value;adaData=E.classData(adaSeed);ada=E.adaBoost(adaData.train,adaCount);adaFrame=0;adaControls();adaView();};$('#ada-count').onchange=change;$('#ada-seed').onchange=e=>{if(e.target.checkValidity())change();};}
function adaView(){const n=ada.rounds.length;if(!n){$('#view').innerHTML=`<section class="card">${tr('No se encontró un árbol mejor que el azar. Cambia la semilla.','No tree better than chance was found. Change the seed.')}</section>`;return;}adaFrame=Math.min(adaFrame,n*3-1);const index=Math.floor(adaFrame/3),phase=adaFrame%3,m=ada.rounds[index],visiblePredict=r=>adaPanel==='tree'?m.predict(r):ada.predict(r,index+1),error=rows=>100*rows.filter(r=>visiblePredict(r)!==r.y).length/rows.length;
$('#view').innerHTML=`<section class="card"><p class="eyebrow">ADABOOST · ${tr('CLASIFICACIÓN BINARIA','BINARY CLASSIFICATION')}</p><h2>${tr('Los errores reciben más peso','Errors receive more weight')}</h2>${animationButtons()}<p class="flow"><strong>${tr('Ronda','Round')} ${index+1} / ${n} · ${[tr('1. Entrenar con los pesos actuales','1. Train with current weights'),tr('2. Identificar errores del árbol','2. Identify tree errors'),tr('3. Actualizar pesos para la próxima ronda','3. Update weights for the next round')][phase]}</strong></p><div class="tabs"><button data-ada-panel="tree" aria-current="${adaPanel==='tree'}">${tr('Árbol de la ronda','Current tree')}</button><button data-ada-panel="ensemble" aria-current="${adaPanel==='ensemble'}">${tr('Ensemble acumulado','Accumulated ensemble')}</button></div><canvas id="ada-plot" width="850" height="320" role="img" aria-label="${tr('Clases, pesos y frontera de decisión','Classes, weights and decision boundary')}"></canvas><p class="legend"><span style="color:#225b9a">● ${tr('Clase 0','Class 0')}</span><span style="color:#c45d16">● ${tr('Clase 1','Class 1')}</span><span>${tr('Halo = peso · Centro = posición exacta','Halo = weight · Center = exact position')} · ${adaPanel==='tree'?tr('Aro rojo = error del árbol de esta ronda','Red ring = current tree error'):tr('Aro rojo = error del ensemble acumulado','Red ring = accumulated ensemble error')}</span></p><p>${adaPanel==='ensemble'?tr('El fondo y los aros muestran el resultado combinado hasta esta ronda. El halo indica el peso y puede cruzar la frontera: comprueba el centro y el aro rojo.','Background and rings show the combined result up to this round. The weight halo may cross the boundary: check the center and red ring.'):phase===2?tr('Los puntos que este árbol falla crecen; los que acierta reducen su peso relativo. Estos pesos entrenarán el siguiente árbol.','Points this tree gets wrong grow; correct points lose relative weight. These weights will train the next tree.'):tr('Cada árbol busca un corte que minimice el error ponderado. Los puntos grandes cuentan más.','Each tree finds a split minimizing weighted error. Large points count more.')}</p><p class="equation">${m.axis==='x'?'x₁':'x₂'} ≤ ${f(m.cut)} · ε = ${f(m.error)} · α = ${f(m.alpha)}</p><div class="scores"><div>${adaPanel==='tree'?tr('Error del árbol · entrenamiento','Tree error · training'):tr('Error del ensemble · entrenamiento','Ensemble error · training')}<strong>${error(adaData.train).toFixed(1)}%</strong><small>${adaData.train.filter(r=>visiblePredict(r)!==r.y).length} / ${adaData.train.length} ${tr('errores','errors')}</small></div><div>${adaPanel==='tree'?tr('Error del árbol · validación','Tree error · validation'):tr('Error del ensemble · validación','Ensemble error · validation')}<strong>${error(adaData.validation).toFixed(1)}%</strong></div></div><p class="note">${tr('El fondo representa la clase predicha. Se dibujan solo puntos de entrenamiento; validación no modifica los pesos. Las métricas corresponden a la pestaña seleccionada. El porcentaje de error cuenta cada ejemplo una vez; ε usa los pesos de esta ronda.','Background shows predicted class. Only training points are drawn; validation never changes weights. Metrics match the selected tab. Error percentage counts each sample once; ε uses this round’s weights.')}</p>${adaFrame===n*3-1?`<p role="status"><strong>${ada.rounds.at(-1).error<=1e-12?tr('Parada anticipada: árbol sin errores.','Stopped early: error-free tree.'):n<adaCount?tr('Parada anticipada: ningún árbol mejora el azar.','Stopped early: no tree beats chance.'):tr('Límite de rondas alcanzado.','Round limit reached.')}</strong> ${tr('El resultado es el voto ponderado de todos los árboles, no el último árbol. Puede conservar errores; no tiene por qué mejorar en cada ronda.','The result is the weighted vote of all trees, not the last tree. Errors can remain; improvement is not guaranteed at every round.')}</p>${n===adaCount&&adaCount<60?`<button class="secondary" id="ada-continue">${tr('Continuar 12 rondas más','Continue for 12 more rounds')}</button>`:''}`:''}<details><summary>${tr('Cómo combina los árboles','How trees are combined')}</summary><p>α = ½ ln((1 − ε) / ε)</p><p>${tr('Voto ponderado por α: los árboles con menor error ponderado reciben más influencia. Para el cálculo interno, las clases son −1 y +1.','Vote weighted by α: trees with lower weighted error receive more influence. Internally, labels are −1 and +1.')}</p><p>wᵢ ← wᵢ exp(−α yᵢ h(xᵢ)); ${tr('normalizar para sumar 1.','normalize to sum to 1.')}</p><p>${tr('Se detiene antes si el árbol es perfecto o no mejora el azar. AdaBoost cambia pesos; Gradient Boosting aprende residuos.','Stops early for a perfect tree or if no tree beats chance. AdaBoost changes weights; Gradient Boosting learns residuals.')}</p></details></section>`;
const c=$('#ada-plot'),ctx=c.getContext('2d'),p=28,w=c.width-2*p,h=c.height-2*p,weights=phase===2?m.after:m.before;const shown=adaPanel==='tree'?[m]:ada.rounds.slice(0,index+1),cuts=axis=>[0,...new Set(shown.filter(t=>t.axis===axis&&t.cut>0&&t.cut<1).map(t=>t.cut)),1].sort((a,b)=>a-b),xs=cuts('x'),zs=cuts('z');for(let i=0;i<xs.length-1;i++)for(let j=0;j<zs.length-1;j++){const r={x:(xs[i]+xs[i+1])/2,z:(zs[j]+zs[j+1])/2},label=adaPanel==='tree'?m.predict(r):ada.predict(r,index+1);ctx.fillStyle=label===1?'#fff0df':'#e5effc';ctx.fillRect(p+xs[i]*w,p+(1-zs[j+1])*h,(xs[i+1]-xs[i])*w,(zs[j+1]-zs[j])*h);} adaData.train.forEach((r,i)=>{const x=p+r.x*w,y=p+(1-r.z)*h,radius=Math.sqrt(weights[i]*adaData.train.length)*5;ctx.beginPath();ctx.arc(x,y,radius,0,Math.PI*2);ctx.fillStyle=r.y===1?'#c45d16':'#225b9a';ctx.globalAlpha=.35;ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=r.y===1?'#c45d16':'#225b9a';ctx.lineWidth=1;ctx.stroke();ctx.beginPath();ctx.arc(x,y,2,0,Math.PI*2);ctx.fill();if((adaPanel==='ensemble'||phase>0)&&(adaPanel==='tree'?m.predict(r):ada.predict(r,index+1))!==r.y){ctx.beginPath();ctx.arc(x,y,radius+3,0,Math.PI*2);ctx.strokeStyle='#d52338';ctx.lineWidth=2;ctx.stroke();}});ctx.fillStyle='#18365d';ctx.font='14px system-ui';ctx.fillText('x₁',c.width/2,c.height-3);ctx.fillText('x₂',3,18);
bindAnimation(()=>{if(adaFrame>=n*3-1)return false;adaFrame++;if(adaFrame===n*3-1)adaPanel='ensemble';return adaFrame<n*3-1;},()=>{adaFrame=0;adaPanel='tree';},adaView);if($('#ada-continue'))$('#ada-continue').onclick=()=>{pauseAnimation();adaCount=Math.min(60,adaCount+12);ada=E.adaBoost(adaData.train,adaCount);classificationControls();adaView();$('#play').click();};document.querySelectorAll('[data-ada-panel]').forEach(b=>b.onclick=()=>{adaPanel=b.dataset.adaPanel;adaView();});}

$('#problem').onchange=e=>{pauseAnimation();problem=e.target.value;if(problem==='regression')compute();if(tab==='adaboost'&&problem==='regression')tab='bagging';member=0;step=0;fold=0;boostStage=1;adaFrame=0;bagPanel=problem==='classification'?'ensemble':'prediction';render();};
$('#language').onchange=e=>{lang=e.target.value;render();announce('');};render();
